"""Sortie A3, batch 10: the elementary analytic inputs of the eventual bounds
(A3-blueprint.md section 2.7): the exponential beats a multiple of the square,
and a real power beats a constant, each with an explicit threshold."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); import a3lib
from tm import *
from lin import linarith
from a3lib import lineq
import num
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

# ------------------------------------------------------------ extrwexpsq
w = W('extrwexpsq', 'The exponential beats a multiple of the square: C U ^ 2 <_ exp ( D U ) as soon as ( 27 C ) / D ^ 3 <_ U (the explicit-threshold form of Lean\'s eventually_sq_le_expW and of the hexp2 step of eventually_uW).')
A = '( ( D x. U ) / 3 )'
H = '( ( U e. RR /\\ C e. RR /\\ D e. RR ) /\\ ( 0 < C /\\ 0 < D ) /\\ ( ( ; 2 7 x. C ) / ( D ^ 3 ) ) <_ U )'
ure = w.s([], 'simp11', '( %s -> U e. RR )' % H)
cre = w.s([], 'simp12', '( %s -> C e. RR )' % H)
dre = w.s([], 'simp13', '( %s -> D e. RR )' % H)
c0 = w.s([], 'simp2l', '( %s -> 0 < C )' % H)
d0 = w.s([], 'simp2r', '( %s -> 0 < D )' % H)
thr = w.s([], 'simp3', '( %s -> ( ( ; 2 7 x. C ) / ( D ^ 3 ) ) <_ U )' % H)
drp = w.s([dre, d0], 'elrpd', '( %s -> D e. RR+ )' % H)
d3rp = w.s([drp, w.s([w.s([w.s([], '3nn0', '3 e. NN0')], 'a1i', '( %s -> 3 e. NN0 )' % H)], 'nn0zd', '( %s -> 3 e. ZZ )' % H)], 'rpexpcld', '( %s -> ( D ^ 3 ) e. RR+ )' % H)
d3re = w.s([d3rp], 'rpred', '( %s -> ( D ^ 3 ) e. RR )' % H)
d30 = w.s([d3rp], 'rpgt0d', '( %s -> 0 < ( D ^ 3 ) )' % H)
i27 = w.s([num.fact(w, '; 2 7', 'RR')], 'a1i', '( %s -> ; 2 7 e. RR )' % H)
i270 = w.s([num.fact(w, '; 2 7', 'gt0')], 'a1i', '( %s -> 0 < ; 2 7 )' % H)
c27 = w.s([i27, cre], 'remulcld', '( %s -> ( ; 2 7 x. C ) e. RR )' % H)
c270 = w.s([i270, c0], 'mulgt0d', '( %s -> 0 < ( ; 2 7 x. C ) )' % H)
# the threshold in product form: ( 27 C ) <_ ( D ^ 3 ) x. U
d3p = w.s([d3re, d30], 'jca', '( %s -> ( ( D ^ 3 ) e. RR /\\ 0 < ( D ^ 3 ) ) )' % H)
thr2 = w.s([w.s([c27, ure, d3p, w.inst('ledivmul')], 'syl3anc', '( %s -> ( ( ( ; 2 7 x. C ) / ( D ^ 3 ) ) <_ U <-> ( ; 2 7 x. C ) <_ ( ( D ^ 3 ) x. U ) ) )' % H), thr], 'mpbid', '( %s -> ( ; 2 7 x. C ) <_ ( ( D ^ 3 ) x. U ) )' % H)
# 0 < U
q0 = w.s([c270, d30], 'divgt0d', '( %s -> 0 < ( ( ; 2 7 x. C ) / ( D ^ 3 ) ) )' % H)
qre = w.s([c27, d3re, w.s([d30], 'gt0ne0d', '( %s -> ( D ^ 3 ) =/= 0 )' % H)], 'redivcld', '( %s -> ( ( ; 2 7 x. C ) / ( D ^ 3 ) ) e. RR )' % H)
u0 = w.s([w.s([], '0red', '( %s -> 0 e. RR )' % H), qre, ure, q0, thr], 'ltletrd', '( %s -> 0 < U )' % H)
# A = ( D U ) / 3
duo = w.s([w.s([dre, ure], 'remulcld', '( %s -> ( D x. U ) e. RR )' % H), w.s([d0, u0], 'mulgt0d', '( %s -> 0 < ( D x. U ) )' % H)], 'elrpd', '( %s -> ( D x. U ) e. RR+ )' % H)
i3rp = w.s([num.fact(w, '3', 'RR+')], 'a1i', '( %s -> 3 e. RR+ )' % H)
arp = w.s([duo, i3rp], 'rpdivcld', '( %s -> %s e. RR+ )' % (H, A))
are = w.s([arp], 'rpred', '( %s -> %s e. RR )' % (H, A))
age0 = w.s([arp], 'rpge0d', '( %s -> 0 <_ %s )' % (H, A))
ef = w.s([arp, w.inst('efgt1p')], 'syl', '( %s -> ( 1 + %s ) < ( exp ` %s ) )' % (H, A, A))
a1re = w.s([w.s([], '1red', '( %s -> 1 e. RR )' % H), are], 'readdcld', '( %s -> ( 1 + %s ) e. RR )' % (H, A))
efre = w.s([w.s([are, w.inst('rpefcl')], 'syl', '( %s -> ( exp ` %s ) e. RR+ )' % (H, A))], 'rpred', '( %s -> ( exp ` %s ) e. RR )' % (H, A))
i3n0 = w.s([w.s([], '3nn0', '3 e. NN0')], 'a1i', '( %s -> 3 e. NN0 )' % H)
dure = w.s([dre, ure], 'remulcld', '( %s -> ( D x. U ) e. RR )' % H)
ale = linarith(w, H, [age0], '%s <_ ( 1 + %s )' % (A, A), leaves={'( D x. U )': ('RR', dure)})
a1ge0 = linarith(w, H, [age0], '0 <_ ( 1 + %s )' % A, leaves={'( D x. U )': ('RR', dure)})
p1 = w.s([w.s([w.s([are, a1re, i3n0], '3jca', '( %s -> ( %s e. RR /\\ ( 1 + %s ) e. RR /\\ 3 e. NN0 ) )' % (H, A, A)), w.s([age0, ale], 'jca', '( %s -> ( 0 <_ %s /\\ %s <_ ( 1 + %s ) ) )' % (H, A, A, A))], 'jca', '( %s -> ( ( %s e. RR /\\ ( 1 + %s ) e. RR /\\ 3 e. NN0 ) /\\ ( 0 <_ %s /\\ %s <_ ( 1 + %s ) ) ) )' % (H, A, A, A, A, A)), w.inst('leexp1a')], 'syl', '( %s -> ( %s ^ 3 ) <_ ( ( 1 + %s ) ^ 3 ) )' % (H, A, A))
p2 = w.s([w.s([w.s([a1re, efre, i3n0], '3jca', '( %s -> ( ( 1 + %s ) e. RR /\\ ( exp ` %s ) e. RR /\\ 3 e. NN0 ) )' % (H, A, A)), w.s([a1ge0, w.s([ef], 'ltled', '( %s -> ( 1 + %s ) <_ ( exp ` %s ) )' % (H, A, A))], 'jca', '( %s -> ( 0 <_ ( 1 + %s ) /\\ ( 1 + %s ) <_ ( exp ` %s ) ) )' % (H, A, A, A))], 'jca', '( %s -> ( ( ( 1 + %s ) e. RR /\\ ( exp ` %s ) e. RR /\\ 3 e. NN0 ) /\\ ( 0 <_ ( 1 + %s ) /\\ ( 1 + %s ) <_ ( exp ` %s ) ) ) )' % (H, A, A, A, A, A)), w.inst('leexp1a')], 'syl', '( %s -> ( ( 1 + %s ) ^ 3 ) <_ ( ( exp ` %s ) ^ 3 ) )' % (H, A, A))
a3re = w.s([are, i3n0], 'reexpcld', '( %s -> ( %s ^ 3 ) e. RR )' % (H, A))
a13re = w.s([a1re, i3n0], 'reexpcld', '( %s -> ( ( 1 + %s ) ^ 3 ) e. RR )' % (H, A))
ef3re = w.s([efre, i3n0], 'reexpcld', '( %s -> ( ( exp ` %s ) ^ 3 ) e. RR )' % (H, A))
p3 = w.s([a3re, a13re, ef3re, p1, p2], 'letrd', '( %s -> ( %s ^ 3 ) <_ ( ( exp ` %s ) ^ 3 ) )' % (H, A, A))
# ( exp A ) ^ 3 = exp ( D U )
i3z = w.s([i3n0], 'nn0zd', '( %s -> 3 e. ZZ )' % H)
ee = w.s([w.s([are], 'recnd', '( %s -> %s e. CC )' % (H, A)), i3z, w.inst('efexp')], 'syl2anc', '( %s -> ( exp ` ( 3 x. %s ) ) = ( ( exp ` %s ) ^ 3 ) )' % (H, A, A))
i3cn = w.s([num.cc(w, '3')], 'a1i', '( %s -> 3 e. CC )' % H)
i3ne = w.s([num.fact(w, '3', 'ne0')], 'a1i', '( %s -> 3 =/= 0 )' % H)
dcan = w.s([w.s([w.s([dre, ure], 'remulcld', '( %s -> ( D x. U ) e. RR )' % H)], 'recnd', '( %s -> ( D x. U ) e. CC )' % H), i3cn, i3ne], 'divcan2d', '( %s -> ( 3 x. %s ) = ( D x. U ) )' % (H, A))
ee2 = w.s([w.s([dcan], 'fveq2d', '( %s -> ( exp ` ( 3 x. %s ) ) = ( exp ` ( D x. U ) ) )' % (H, A)), ee], 'eqtr3d', '( %s -> ( exp ` ( D x. U ) ) = ( ( exp ` %s ) ^ 3 ) )' % (H, A))
p4 = w.s([p3, ee2], 'breqtrrd', '( %s -> ( %s ^ 3 ) <_ ( exp ` ( D x. U ) ) )' % (H, A))
# A ^ 3 = ( ( D ^ 3 ) x. ( U ^ 3 ) ) / 27
ducn = w.s([w.s([dre, ure], 'remulcld', '( %s -> ( D x. U ) e. RR )' % H)], 'recnd', '( %s -> ( D x. U ) e. CC )' % H)
i3p = w.s([i3cn, i3ne], 'jca', '( %s -> ( 3 e. CC /\\ 3 =/= 0 ) )' % H)
edh = w.s([ducn, i3p, i3n0], '3jca', '( %s -> ( ( D x. U ) e. CC /\\ ( 3 e. CC /\\ 3 =/= 0 ) /\\ 3 e. NN0 ) )' % H)
ed = w.s([edh, w.inst('expdiv')], 'syl', '( %s -> ( %s ^ 3 ) = ( ( ( D x. U ) ^ 3 ) / ( 3 ^ 3 ) ) )' % (H, A))
i33 = w.s([w.s([], '3exp3', '( 3 ^ 3 ) = ; 2 7')], 'a1i', '( %s -> ( 3 ^ 3 ) = ; 2 7 )' % H)
me = w.s([w.s([w.s([dre], 'recnd', '( %s -> D e. CC )' % H), w.s([ure], 'recnd', '( %s -> U e. CC )' % H), i3n0], '3jca', '( %s -> ( D e. CC /\\ U e. CC /\\ 3 e. NN0 ) )' % H), w.inst('mulexp')], 'syl', '( %s -> ( ( D x. U ) ^ 3 ) = ( ( D ^ 3 ) x. ( U ^ 3 ) ) )' % H)
ed2 = w.s([ed, w.s([me, i33], 'oveq12d', '( %s -> ( ( ( D x. U ) ^ 3 ) / ( 3 ^ 3 ) ) = ( ( ( D ^ 3 ) x. ( U ^ 3 ) ) / ; 2 7 ) )' % H)], 'eqtrd', '( %s -> ( %s ^ 3 ) = ( ( ( D ^ 3 ) x. ( U ^ 3 ) ) / ; 2 7 ) )' % (H, A))
# 27 ( C U ^ 2 ) <_ ( D ^ 3 ) ( U ^ 3 )
u2re = w.s([ure, w.s([w.s([], '2nn0', '2 e. NN0')], 'a1i', '( %s -> 2 e. NN0 )' % H)], 'reexpcld', '( %s -> ( U ^ 2 ) e. RR )' % H)
i2n0 = w.s([w.s([], '2nn0', '2 e. NN0')], 'a1i', '( %s -> 2 e. NN0 )' % H)
uge0 = linarith(w, H, [u0], '0 <_ U', leaves={'U': ('RR', ure)})
u2ge0 = w.s([ure, i2n0, uge0], 'expge0d', '( %s -> 0 <_ ( U ^ 2 ) )' % H)
d3ure = w.s([d3re, ure], 'remulcld', '( %s -> ( ( D ^ 3 ) x. U ) e. RR )' % H)
u2p = w.s([u2re, u2ge0], 'jca', '( %s -> ( ( U ^ 2 ) e. RR /\\ 0 <_ ( U ^ 2 ) ) )' % H)
m1a = w.s([c27, d3ure, u2p], '3jca', '( %s -> ( ( ; 2 7 x. C ) e. RR /\\ ( ( D ^ 3 ) x. U ) e. RR /\\ ( ( U ^ 2 ) e. RR /\\ 0 <_ ( U ^ 2 ) ) ) )' % H)
mul1 = w.s([m1a, thr2], 'jca', '( %s -> ( ( ( ; 2 7 x. C ) e. RR /\\ ( ( D ^ 3 ) x. U ) e. RR /\\ ( ( U ^ 2 ) e. RR /\\ 0 <_ ( U ^ 2 ) ) ) /\\ ( ; 2 7 x. C ) <_ ( ( D ^ 3 ) x. U ) ) )' % H)
mul2 = w.s([mul1, w.inst('lemul1a')], 'syl', '( %s -> ( ( ; 2 7 x. C ) x. ( U ^ 2 ) ) <_ ( ( ( D ^ 3 ) x. U ) x. ( U ^ 2 ) ) )' % H)
ccn = w.s([cre], 'recnd', '( %s -> C e. CC )' % H)
ucn = w.s([ure], 'recnd', '( %s -> U e. CC )' % H)
u2cn = w.s([u2re], 'recnd', '( %s -> ( U ^ 2 ) e. CC )' % H)
d3cn = w.s([d3re], 'recnd', '( %s -> ( D ^ 3 ) e. CC )' % H)
i27cn = w.s([num.cc(w, '; 2 7')], 'a1i', '( %s -> ; 2 7 e. CC )' % H)
e1 = w.s([i27cn, ccn, u2cn], 'mulassd', '( %s -> ( ( ; 2 7 x. C ) x. ( U ^ 2 ) ) = ( ; 2 7 x. ( C x. ( U ^ 2 ) ) ) )' % H)
e2 = w.s([d3cn, ucn, u2cn], 'mulassd', '( %s -> ( ( ( D ^ 3 ) x. U ) x. ( U ^ 2 ) ) = ( ( D ^ 3 ) x. ( U x. ( U ^ 2 ) ) ) )' % H)
e3a = w.s([ucn, i2n0], 'expp1d', '( %s -> ( U ^ ( 2 + 1 ) ) = ( ( U ^ 2 ) x. U ) )' % H)
e3b = w.s([w.s([w.s([], '2p1e3', '( 2 + 1 ) = 3')], 'a1i', '( %s -> ( 2 + 1 ) = 3 )' % H)], 'oveq2d', '( %s -> ( U ^ ( 2 + 1 ) ) = ( U ^ 3 ) )' % H)
e3c = w.s([u2cn, ucn], 'mulcomd', '( %s -> ( ( U ^ 2 ) x. U ) = ( U x. ( U ^ 2 ) ) )' % H)
e3 = w.s([w.s([w.s([e3b], 'eqcomd', '( %s -> ( U ^ 3 ) = ( U ^ ( 2 + 1 ) ) )' % H), e3a], 'eqtrd', '( %s -> ( U ^ 3 ) = ( ( U ^ 2 ) x. U ) )' % H), e3c], 'eqtrd', '( %s -> ( U ^ 3 ) = ( U x. ( U ^ 2 ) ) )' % H)
e4 = w.s([e2, w.s([w.s([e3], 'eqcomd', '( %s -> ( U x. ( U ^ 2 ) ) = ( U ^ 3 ) )' % H)], 'oveq2d', '( %s -> ( ( D ^ 3 ) x. ( U x. ( U ^ 2 ) ) ) = ( ( D ^ 3 ) x. ( U ^ 3 ) ) )' % H)], 'eqtrd', '( %s -> ( ( ( D ^ 3 ) x. U ) x. ( U ^ 2 ) ) = ( ( D ^ 3 ) x. ( U ^ 3 ) ) )' % H)
mul3 = w.s([w.s([w.s([e1], 'eqcomd', '( %s -> ( ; 2 7 x. ( C x. ( U ^ 2 ) ) ) = ( ( ; 2 7 x. C ) x. ( U ^ 2 ) ) )' % H), mul2], 'eqbrtrd', '( %s -> ( ; 2 7 x. ( C x. ( U ^ 2 ) ) ) <_ ( ( ( D ^ 3 ) x. U ) x. ( U ^ 2 ) ) )' % H), e4], 'breqtrd', '( %s -> ( ; 2 7 x. ( C x. ( U ^ 2 ) ) ) <_ ( ( D ^ 3 ) x. ( U ^ 3 ) ) )' % H)
cu2re = w.s([cre, u2re], 'remulcld', '( %s -> ( C x. ( U ^ 2 ) ) e. RR )' % H)
u3re = w.s([ure, i3n0], 'reexpcld', '( %s -> ( U ^ 3 ) e. RR )' % H)
d3u3re = w.s([d3re, u3re], 'remulcld', '( %s -> ( ( D ^ 3 ) x. ( U ^ 3 ) ) e. RR )' % H)
i27p = w.s([i27, i270], 'jca', '( %s -> ( ; 2 7 e. RR /\\ 0 < ; 2 7 ) )' % H)
div = w.s([w.s([cu2re, d3u3re, i27p, w.inst('lemuldiv2')], 'syl3anc', '( %s -> ( ( ; 2 7 x. ( C x. ( U ^ 2 ) ) ) <_ ( ( D ^ 3 ) x. ( U ^ 3 ) ) <-> ( C x. ( U ^ 2 ) ) <_ ( ( ( D ^ 3 ) x. ( U ^ 3 ) ) / ; 2 7 ) ) )' % H), mul3], 'mpbid', '( %s -> ( C x. ( U ^ 2 ) ) <_ ( ( ( D ^ 3 ) x. ( U ^ 3 ) ) / ; 2 7 ) )' % H)
fin1 = w.s([div, ed2], 'breqtrrd', '( %s -> ( C x. ( U ^ 2 ) ) <_ ( %s ^ 3 ) )' % (H, A))
efdu = w.s([w.s([w.s([dre, ure], 'remulcld', '( %s -> ( D x. U ) e. RR )' % H), w.inst('rpefcl')], 'syl', '( %s -> ( exp ` ( D x. U ) ) e. RR+ )' % H)], 'rpred', '( %s -> ( exp ` ( D x. U ) ) e. RR )' % H)
w.qed([cu2re, a3re, efdu, fin1, p4], 'letrd', '( %s -> ( C x. ( U ^ 2 ) ) <_ ( exp ` ( D x. U ) ) )' % H)
run(w)

# ------------------------------------------------------------ extrwrpow
w = W('extrwrpow', 'A real power beats a constant past an explicit threshold: B <_ ( U ^c G ) as soon as ( B ^c ( 1 / G ) ) <_ U (the explicit-threshold form of Mathlib\'s tendsto_rpow_atTop, used by star_boundW and eventually_uW).')
H = '( ( B e. RR+ /\\ G e. RR+ /\\ U e. RR ) /\\ ( B ^c ( 1 / G ) ) <_ U )'
BG = '( B ^c ( 1 / G ) )'
brp = w.s([], 'simpl1', '( %s -> B e. RR+ )' % H)
grp = w.s([], 'simpl2', '( %s -> G e. RR+ )' % H)
ure = w.s([], 'simpl3', '( %s -> U e. RR )' % H)
thr = w.s([], 'simpr', '( %s -> %s <_ U )' % (H, BG))
gre = w.s([grp], 'rpred', '( %s -> G e. RR )' % H)
gge0 = w.s([grp], 'rpge0d', '( %s -> 0 <_ G )' % H)
ginv = w.s([w.s([w.s([], '1rp', '1 e. RR+')], 'a1i', '( %s -> 1 e. RR+ )' % H), grp], 'rpdivcld', '( %s -> ( 1 / G ) e. RR+ )' % H)
bgrp = w.s([brp, w.s([ginv], 'rpred', '( %s -> ( 1 / G ) e. RR )' % H), w.inst('rpcxpcl')], 'syl2anc', '( %s -> %s e. RR+ )' % (H, BG))
bgre = w.s([bgrp], 'rpred', '( %s -> %s e. RR )' % (H, BG))
bgge0 = w.s([bgrp], 'rpge0d', '( %s -> 0 <_ %s )' % (H, BG))
mono = w.s([w.s([w.s([bgre, ure, gre], '3jca', '( %s -> ( %s e. RR /\\ U e. RR /\\ G e. RR ) )' % (H, BG)), w.s([bgge0, gge0], 'jca', '( %s -> ( 0 <_ %s /\\ 0 <_ G ) )' % (H, BG)), thr], '3jca', '( %s -> ( ( %s e. RR /\\ U e. RR /\\ G e. RR ) /\\ ( 0 <_ %s /\\ 0 <_ G ) /\\ %s <_ U ) )' % (H, BG, BG, BG)), w.inst('cxple2a')], 'syl', '( %s -> ( %s ^c G ) <_ ( U ^c G ) )' % (H, BG))
cm = w.s([brp, w.s([ginv], 'rpred', '( %s -> ( 1 / G ) e. RR )' % H), w.s([gre], 'recnd', '( %s -> G e. CC )' % H), w.inst('cxpmul')], 'syl3anc', '( %s -> ( B ^c ( ( 1 / G ) x. G ) ) = ( %s ^c G ) )' % (H, BG))
rec = w.s([w.s([gre], 'recnd', '( %s -> G e. CC )' % H), w.s([grp], 'rpne0d', '( %s -> G =/= 0 )' % H)], 'recid2d', '( %s -> ( ( 1 / G ) x. G ) = 1 )' % H)
cm2 = w.s([w.s([rec], 'oveq2d', '( %s -> ( B ^c ( ( 1 / G ) x. G ) ) = ( B ^c 1 ) )' % H), w.s([w.s([brp], 'rpcnd', '( %s -> B e. CC )' % H), w.inst('cxp1')], 'syl', '( %s -> ( B ^c 1 ) = B )' % H)], 'eqtrd', '( %s -> ( B ^c ( ( 1 / G ) x. G ) ) = B )' % H)
eq = w.s([w.s([cm2], 'eqcomd', '( %s -> B = ( B ^c ( ( 1 / G ) x. G ) ) )' % H), cm], 'eqtrd', '( %s -> B = ( %s ^c G ) )' % (H, BG))
w.qed([eq, mono], 'eqbrtrd', '( %s -> B <_ ( U ^c G ) )' % H)
run(w)

# ------------------------------------------------------------ extrwlogle
w = W('extrwlogle', 'log X <_ X - 1 for X >= 1 (Mathlib: Real.log_le_sub_one_of_pos, in the range star_boundW and eventually_uW use it).')
H = '( X e. RR /\\ 1 <_ X )'
xre = w.s([], 'simpl', '( %s -> X e. RR )' % H)
x1 = w.s([], 'simpr', '( %s -> 1 <_ X )' % H)
# case 1 < X
CA = '( %s /\\ 1 < X )' % H
xreA = w.s([xre], 'adantr', '( %s -> X e. RR )' % CA)
x1A = w.s([], 'simpr', '( %s -> 1 < X )' % CA)
xm1 = w.s([w.s([xreA, w.s([], '1red', '( %s -> 1 e. RR )' % CA)], 'resubcld', '( %s -> ( X - 1 ) e. RR )' % CA), linarith(w, CA, [x1A], '0 < ( X - 1 )', leaves={'X': ('RR', xreA)})], 'elrpd', '( %s -> ( X - 1 ) e. RR+ )' % CA)
ef = w.s([xm1, w.inst('efgt1p')], 'syl', '( %s -> ( 1 + ( X - 1 ) ) < ( exp ` ( X - 1 ) ) )' % CA)
eq1 = w.s([w.s([xreA], 'recnd', '( %s -> X e. CC )' % CA), w.s([], '1cnd', '( %s -> 1 e. CC )' % CA)], 'pncan3d', '( %s -> ( 1 + ( X - 1 ) ) = X )' % CA)
lt1 = w.s([eq1, ef], 'eqbrtrrd', '( %s -> X < ( exp ` ( X - 1 ) ) )' % CA)
xrp = w.s([xreA, linarith(w, CA, [x1A], '0 < X', leaves={'X': ('RR', xreA)})], 'elrpd', '( %s -> X e. RR+ )' % CA)
efrp = w.s([w.s([xm1], 'rpred', '( %s -> ( X - 1 ) e. RR )' % CA), w.inst('rpefcl')], 'syl', '( %s -> ( exp ` ( X - 1 ) ) e. RR+ )' % CA)
lt2 = w.s([w.s([xrp, efrp, w.inst('logltb')], 'syl2anc', '( %s -> ( X < ( exp ` ( X - 1 ) ) <-> ( log ` X ) < ( log ` ( exp ` ( X - 1 ) ) ) ) )' % CA), lt1], 'mpbid', '( %s -> ( log ` X ) < ( log ` ( exp ` ( X - 1 ) ) ) )' % CA)
lt3 = w.s([lt2, w.s([w.s([xm1], 'rpred', '( %s -> ( X - 1 ) e. RR )' % CA), w.inst('relogef')], 'syl', '( %s -> ( log ` ( exp ` ( X - 1 ) ) ) = ( X - 1 ) )' % CA)], 'breqtrd', '( %s -> ( log ` X ) < ( X - 1 ) )' % CA)
caseA = w.s([lt3], 'ltled', '( %s -> ( log ` X ) <_ ( X - 1 ) )' % CA)
# case X = 1
CB = '( %s /\\ -. 1 < X )' % H
xreB = w.s([xre], 'adantr', '( %s -> X e. RR )' % CB)
