caseB = w.s([w.s([lg1, w.s([w.s([], '0le0', '0 <_ 0')], 'a1i', '( %s -> 0 <_ 0 )' % CB)], 'eqbrtrd', '( %s -> ( log ` X ) <_ 0 )' % CB), sub1], 'breqtrrd', '( %s -> ( log ` X ) <_ ( X - 1 ) )' % CB)
