# ------------------------------------------------------------ extrwzb
w = W('extrwzb', 'The z-bounds of star_boundW: at windowed scales with ell2 >= 50 and ell3 >= 1, z exceeds 1 and its logarithm is between ell3 and 3 ell3.')
CA0 = '( ( C x. A ) x. B )'
H = '( ( ( C e. RR /\\ ; ; ; 1 0 0 0 <_ C ) /\\ ( A e. RR /\\ B e. RR /\\ B = ( log ` A ) ) ) /\\ ( ( ; 5 0 <_ A /\\ 1 <_ B /\\ ( log ` ( 4 x. C ) ) <_ B ) /\\ ( Z e. NN0 /\\ %s <_ Z /\\ Z <_ ( 4 x. %s ) ) ) )' % (CA0, CA0)
cb = w.s([], 'simpll', '( %s -> ( C e. RR /\\ ; ; ; 1 0 0 0 <_ C ) )' % H)
ab = w.s([], 'simplr', '( %s -> ( A e. RR /\\ B e. RR /\\ B = ( log ` A ) ) )' % H)
