b1 = w.s([lo], 'simp2d', '( %s -> 1 <_ B )' % H)
c4b = w.s([lo], 'simp3d', '( %s -> ( log ` ( 4 x. C ) ) <_ B )' % H)
zn0 = w.s([zb], 'simp1d', '( %s -> Z e. NN0 )' % H)
zlo = w.s([zb], 'simp2d', '( %s -> %s <_ Z )' % (H, CA0))
zhi = w.s([zb], 'simp3d', '( %s -> Z <_ ( 4 x. %s ) )' % (H, CA0))
zre = w.s([zn0], 'nn0red', '( %s -> Z e. RR )' % H)
