a1 = linarith(w, H, [a50], '1 <_ A', leaves={'A': ('RR', are)})
a0 = linarith(w, H, [a50], '0 <_ A', leaves={'A': ('RR', are)})
b0 = linarith(w, H, [b1], '0 <_ B', leaves={'B': ('RR', bre)})
