aca = w.s([are, cre, a0, c1], 'lemulge12d', '( %s -> A <_ ( C x. A ) )' % H)
ca0 = linarith(w, H, [a0, aca], '0 <_ ( C x. A )', leaves={'A': ('RR', are), '( C x. A )': ('RR', carr)})
cab = w.s([carr, bre], 'remulcld', '( %s -> %s e. RR )' % (H, CA0))
cacab = w.s([carr, bre, ca0, b1], 'lemulge11d', '( %s -> ( C x. A ) <_ %s )' % (H, CA0))
aleca = w.s([are, carr, cab, aca, cacab], 'letrd', '( %s -> A <_ %s )' % (H, CA0))
alez = w.s([are, cab, zre, aleca, zlo], 'letrd', '( %s -> A <_ Z )' % H)
z1 = linarith(w, H, [a50, alez], '1 < Z', leaves={'A': ('RR', are), 'Z': ('RR', zre)})
zrp = w.s([zre, linarith(w, H, [a50, alez], '0 < Z', leaves={'A': ('RR', are), 'Z': ('RR', zre)})], 'elrpd', '( %s -> Z e. RR+ )' % H)
arp = w.s([are, linarith(w, H, [a50], '0 < A', leaves={'A': ('RR', are)})], 'elrpd', '( %s -> A e. RR+ )' % H)
brp = w.s([bre, linarith(w, H, [b1], '0 < B', leaves={'B': ('RR', bre)})], 'elrpd', '( %s -> B e. RR+ )' % H)
lgle = w.s([w.s([arp, zrp, w.inst('logleb')], 'syl2anc', '( %s -> ( A <_ Z <-> ( log ` A ) <_ ( log ` Z ) ) )' % H), alez], 'mpbid', '( %s -> ( log ` A ) <_ ( log ` Z ) )' % H)
blgz = w.s([beq, lgle], 'eqbrtrd', '( %s -> B <_ ( log ` Z ) )' % H)
