abcn = w.s([acn, bcn], 'mulcld', '( %s -> ( A x. B ) e. CC )' % H)
e1 = w.s([ccn, acn, bcn], 'mulassd', '( %s -> %s = ( C x. ( A x. B ) ) )' % (H, CA0))
e2 = w.s([i4cn, ccn, abcn], 'mulassd', '( %s -> ( ( 4 x. C ) x. ( A x. B ) ) = ( 4 x. ( C x. ( A x. B ) ) ) )' % H)
e3 = w.s([w.s([e1], 'oveq2d', '( %s -> ( 4 x. %s ) = ( 4 x. ( C x. ( A x. B ) ) ) )' % (H, CA0)), w.s([e2], 'eqcomd', '( %s -> ( 4 x. ( C x. ( A x. B ) ) ) = ( ( 4 x. C ) x. ( A x. B ) ) )' % H)], 'eqtrd', '( %s -> ( 4 x. %s ) = ( ( 4 x. C ) x. ( A x. B ) ) )' % (H, CA0))
i4rp = w.s([num.fact(w, '4', 'RR+')], 'a1i', '( %s -> 4 e. RR+ )' % H)
crp = w.s([cre, linarith(w, H, [c1000], '0 < C', leaves={'C': ('RR', cre)})], 'elrpd', '( %s -> C e. RR+ )' % H)
c4rp = w.s([i4rp, crp], 'rpmulcld', '( %s -> ( 4 x. C ) e. RR+ )' % H)
abrp = w.s([arp, brp], 'rpmulcld', '( %s -> ( A x. B ) e. RR+ )' % H)
lm1 = w.s([c4rp, abrp, w.inst('relogmul')], 'syl2anc', '( %s -> ( log ` ( ( 4 x. C ) x. ( A x. B ) ) ) = ( ( log ` ( 4 x. C ) ) + ( log ` ( A x. B ) ) ) )' % H)
lm2 = w.s([arp, brp, w.inst('relogmul')], 'syl2anc', '( %s -> ( log ` ( A x. B ) ) = ( ( log ` A ) + ( log ` B ) ) )' % H)
lm3 = w.s([lm1, w.s([lm2], 'oveq2d', '( %s -> ( ( log ` ( 4 x. C ) ) + ( log ` ( A x. B ) ) ) = ( ( log ` ( 4 x. C ) ) + ( ( log ` A ) + ( log ` B ) ) ) )' % H)], 'eqtrd', '( %s -> ( log ` ( ( 4 x. C ) x. ( A x. B ) ) ) = ( ( log ` ( 4 x. C ) ) + ( ( log ` A ) + ( log ` B ) ) ) )' % H)
lgeq = w.s([w.s([e3], 'fveq2d', '( %s -> ( log ` ( 4 x. %s ) ) = ( log ` ( ( 4 x. C ) x. ( A x. B ) ) ) )' % (H, CA0)), lm3], 'eqtrd', '( %s -> ( log ` ( 4 x. %s ) ) = ( ( log ` ( 4 x. C ) ) + ( ( log ` A ) + ( log ` B ) ) ) )' % (H, CA0))
z4rp = w.s([i4rp, w.s([cab, linarith(w, H, [a50, aleca], '0 < %s' % CA0, leaves={'A': ('RR', are), CA0: ('RR', cab)})], 'elrpd', '( %s -> %s e. RR+ )' % (H, CA0))], 'rpmulcld', '( %s -> ( 4 x. %s ) e. RR+ )' % (H, CA0))
lgz4 = w.s([w.s([zrp, z4rp, w.inst('logleb')], 'syl2anc', '( %s -> ( Z <_ ( 4 x. %s ) <-> ( log ` Z ) <_ ( log ` ( 4 x. %s ) ) ) )' % (H, CA0, CA0)), zhi], 'mpbid', '( %s -> ( log ` Z ) <_ ( log ` ( 4 x. %s ) ) )' % (H, CA0))
lgz5 = w.s([lgz4, lgeq], 'breqtrd', '( %s -> ( log ` Z ) <_ ( ( log ` ( 4 x. C ) ) + ( ( log ` A ) + ( log ` B ) ) ) )' % H)
lgb1 = w.s([w.s([bre, b1], 'jca', '( %s -> ( B e. RR /\\ 1 <_ B ) )' % H), w.inst('extrwlogle')], 'syl', '( %s -> ( log ` B ) <_ ( B - 1 ) )' % H)
lgbre = w.s([brp], 'relogcld', '( %s -> ( log ` B ) e. RR )' % H)
lgbb = linarith(w, H, [lgb1], '( log ` B ) <_ B', leaves={'B': ('RR', bre), '( log ` B )': ('RR', lgbre)})
lgare = w.s([arp], 'relogcld', '( %s -> ( log ` A ) e. RR )' % H)
lgaB = w.s([beq], 'eqcomd', '( %s -> ( log ` A ) = B )' % H)
lgc4re = w.s([c4rp], 'relogcld', '( %s -> ( log ` ( 4 x. C ) ) e. RR )' % H)
lgzre = w.s([zrp], 'relogcld', '( %s -> ( log ` Z ) e. RR )' % H)
fin = linarith(w, H, [lgz5, lgbb, c4b, lgaB], '( log ` Z ) <_ ( 3 x. B )', leaves={'B': ('RR', bre), '( log ` B )': ('RR', lgbre), '( log ` A )': ('RR', lgare), '( log ` ( 4 x. C ) )': ('RR', lgc4re), '( log ` Z )': ('RR', lgzre)})
w.qed([z1, blgz, fin], '3jca', '( %s -> ( 1 < Z /\\ B <_ ( log ` Z ) /\\ ( log ` Z ) <_ ( 3 x. B ) ) )' % H)
