mono = w.s([w.s([w.s([zre, c4ab, e1re], '3jca', '( %s -> ( Z e. RR /\\ ( ( 4 x. C ) x. ( A x. B ) ) e. RR /\\ %s e. RR ) )' % (H, E1)), w.s([zge0, e1ge0], 'jca', '( %s -> ( 0 <_ Z /\\ 0 <_ %s ) )' % (H, E1)), zhi2], '3jca', '( %s -> ( ( Z e. RR /\\ ( ( 4 x. C ) x. ( A x. B ) ) e. RR /\\ %s e. RR ) /\\ ( 0 <_ Z /\\ 0 <_ %s ) /\\ Z <_ ( ( 4 x. C ) x. ( A x. B ) ) ) )' % (H, E1, E1)), w.inst('cxple2a')], 'syl', '( %s -> ( Z ^c %s ) <_ ( ( ( 4 x. C ) x. ( A x. B ) ) ^c %s ) )' % (H, E1, E1))
# split the power of the product
sp1 = w.s([w.s([w.s([c4re, c4ge0], 'jca', '( %s -> ( ( 4 x. C ) e. RR /\\ 0 <_ ( 4 x. C ) ) )' % H), w.s([abre, abge0], 'jca', '( %s -> ( ( A x. B ) e. RR /\\ 0 <_ ( A x. B ) ) )' % H), w.s([e1re], 'recnd', '( %s -> %s e. CC )' % (H, E1))], '3jca', '( %s -> ( ( ( 4 x. C ) e. RR /\\ 0 <_ ( 4 x. C ) ) /\\ ( ( A x. B ) e. RR /\\ 0 <_ ( A x. B ) ) /\\ %s e. CC ) )' % (H, E1)), w.inst('mulcxp')], 'syl', '( %s -> ( ( ( 4 x. C ) x. ( A x. B ) ) ^c %s ) = ( ( ( 4 x. C ) ^c %s ) x. ( ( A x. B ) ^c %s ) ) )' % (H, E1, E1, E1))
sp2 = w.s([w.s([w.s([are, a0], 'jca', '( %s -> ( A e. RR /\\ 0 <_ A ) )' % H), w.s([bre, b0], 'jca', '( %s -> ( B e. RR /\\ 0 <_ B ) )' % H), w.s([e1re], 'recnd', '( %s -> %s e. CC )' % (H, E1))], '3jca', '( %s -> ( ( A e. RR /\\ 0 <_ A ) /\\ ( B e. RR /\\ 0 <_ B ) /\\ %s e. CC ) )' % (H, E1)), w.inst('mulcxp')], 'syl', '( %s -> ( ( A x. B ) ^c %s ) = ( ( A ^c %s ) x. ( B ^c %s ) ) )' % (H, E1, E1, E1))
sp3 = w.s([sp1, w.s([sp2], 'oveq2d', '( %s -> ( ( ( 4 x. C ) ^c %s ) x. ( ( A x. B ) ^c %s ) ) = ( ( ( 4 x. C ) ^c %s ) x. ( ( A ^c %s ) x. ( B ^c %s ) ) ) )' % (H, E1, E1, E1, E1, E1))], 'eqtrd', '( %s -> ( ( ( 4 x. C ) x. ( A x. B ) ) ^c %s ) = ( ( ( 4 x. C ) ^c %s ) x. ( ( A ^c %s ) x. ( B ^c %s ) ) ) )' % (H, E1, E1, E1, E1))
# ( 4 C ) ^c ( 1 - E ) <_ 4 C and B ^c ( 1 - E ) <_ B
c41 = linarith(w, H, [c1000], '1 <_ ( 4 x. C )', leaves={'C': ('RR', cre), '( 4 x. C )': ('RR', c4re)})
