are = w.s([ab], 'simpld', '( %s -> A e. RR )' % H)
a50 = w.s([ab], 'simprd', '( %s -> ; 5 0 <_ A )' % H)
ure = w.s([ub], 'simp1d', '( %s -> U e. RR )' % H)
uge0 = w.s([ub], 'simp2d', '( %s -> 0 <_ U )' % H)
ule = w.s([ub], 'simp3d', '( %s -> U <_ ( exp ` %s ) )' % (H, Q11))
vre = w.s([vb], 'simp1d', '( %s -> V e. RR )' % H)
vge0 = w.s([vb], 'simp2d', '( %s -> 0 <_ V )' % H)
vle = w.s([vb], 'simp3d', '( %s -> V <_ ( exp ` %s ) )' % (H, Q10))
q10re = w.s([w.s([num.real(w, '( 1 / ; 1 0 )')], 'a1i', '( %s -> ( 1 / ; 1 0 ) e. RR )' % H), are], 'remulcld', '( %s -> %s e. RR )' % (H, Q10))
q11re = w.s([w.s([num.real(w, '( ; 1 1 / ; 1 0 )')], 'a1i', '( %s -> ( ; 1 1 / ; 1 0 ) e. RR )' % H), are], 'remulcld', '( %s -> %s e. RR )' % (H, Q11))
q12re = w.s([w.s([num.real(w, '( 6 / 5 )')], 'a1i', '( %s -> ( 6 / 5 ) e. RR )' % H), are], 'remulcld', '( %s -> %s e. RR )' % (H, Q12))
ef11re = w.s([w.s([q11re, w.inst('rpefcl')], 'syl', '( %s -> ( exp ` %s ) e. RR+ )' % (H, Q11))], 'rpred', '( %s -> ( exp ` %s ) e. RR )' % (H, Q11))
ef10re = w.s([w.s([q10re, w.inst('rpefcl')], 'syl', '( %s -> ( exp ` %s ) e. RR+ )' % (H, Q10))], 'rpred', '( %s -> ( exp ` %s ) e. RR )' % (H, Q10))
mul = w.s([ure, ef11re, vre, ef10re, uge0, vge0, ule, vle], 'lemul12ad', '( %s -> ( U x. V ) <_ ( ( exp ` %s ) x. ( exp ` %s ) ) )' % (H, Q11, Q10))
sum1 = lineq(w, H, [], '( %s + %s )' % (Q11, Q10), Q12, {'A': ('RR', are)}, w.s([q11re, q10re], 'readdcld', '( %s -> ( %s + %s ) e. RR )' % (H, Q11, Q10)), q12re, linarith)
efa = w.s([w.s([q11re], 'recnd', '( %s -> %s e. CC )' % (H, Q11)), w.s([q10re], 'recnd', '( %s -> %s e. CC )' % (H, Q10)), w.inst('efadd')], 'syl2anc', '( %s -> ( exp ` ( %s + %s ) ) = ( ( exp ` %s ) x. ( exp ` %s ) ) )' % (H, Q11, Q10, Q11, Q10))
efa2 = w.s([w.s([w.s([sum1], 'fveq2d', '( %s -> ( exp ` ( %s + %s ) ) = ( exp ` %s ) )' % (H, Q11, Q10, Q12))], 'eqcomd', '( %s -> ( exp ` %s ) = ( exp ` ( %s + %s ) ) )' % (H, Q12, Q11, Q10)), efa], 'eqtrd', '( %s -> ( exp ` %s ) = ( ( exp ` %s ) x. ( exp ` %s ) ) )' % (H, Q12, Q11, Q10))
w.qed([mul, efa2], 'breqtrrd', '( %s -> ( U x. V ) <_ ( exp ` %s ) )' % (H, Q12))
