# ------------------------------------------------------------ extrwevan
w = W('extrwevan', 'Two eventual statements combine: if ph holds for all large n and ps holds for all large n then so does their conjunction (the threshold-addition recipe of A1-HANDOFF trap 4, as a reusable schema).')
RA = lambda v, p: 'A. n e. ( ZZ>= ` %s ) %s' % (v, p)
EV = lambda v, p: 'E. %s e. NN0 %s' % (v, RA(v, p))
KL = '( k + l )'
GOAL = EV('m', '( ph /\\ ps )')
H = '( %s /\\ %s )' % (EV('m', 'ph'), EV('m', 'ps'))
# rename the witnesses
cbk = w.s([w.s([w.s([], 'id', '( m = k -> m = k )')], 'fveq2d', '( m = k -> ( ZZ>= ` m ) = ( ZZ>= ` k ) )')], 'raleqdv', '( m = k -> ( %s <-> %s ) )' % (RA('m', 'ph'), RA('k', 'ph')))
ex1 = w.s([w.s([], 'simpl', '( %s -> %s )' % (H, EV('m', 'ph'))), w.s([w.s([cbk], 'cbvrexvw', '( %s <-> %s )' % (EV('m', 'ph'), EV('k', 'ph')))], 'a1i', '( %s -> ( %s <-> %s ) )' % (H, EV('m', 'ph'), EV('k', 'ph')))], 'mpbid', '( %s -> %s )' % (H, EV('k', 'ph')))
cbl = w.s([w.s([w.s([], 'id', '( m = l -> m = l )')], 'fveq2d', '( m = l -> ( ZZ>= ` m ) = ( ZZ>= ` l ) )')], 'raleqdv', '( m = l -> ( %s <-> %s ) )' % (RA('m', 'ps'), RA('l', 'ps')))
ex2 = w.s([w.s([], 'simpr', '( %s -> %s )' % (H, EV('m', 'ps'))), w.s([w.s([cbl], 'cbvrexvw', '( %s <-> %s )' % (EV('m', 'ps'), EV('l', 'ps')))], 'a1i', '( %s -> ( %s <-> %s ) )' % (H, EV('m', 'ps'), EV('l', 'ps')))], 'mpbid', '( %s -> %s )' % (H, EV('l', 'ps')))
# the core, at the threshold k + l
A4 = '( ( ( k e. NN0 /\\ l e. NN0 ) /\\ %s ) /\\ %s )' % (RA('k', 'ph'), RA('l', 'ps'))
kn0 = w.s([], 'simplll', '( %s -> k e. NN0 )' % A4)
ln0 = w.s([], 'simpllr', '( %s -> l e. NN0 )' % A4)
raph = w.s([], 'simplr', '( %s -> %s )' % (A4, RA('k', 'ph')))
raps = w.s([], 'simpr', '( %s -> %s )' % (A4, RA('l', 'ps')))
kz = w.s([kn0], 'nn0zd', '( %s -> k e. ZZ )' % A4)
lz = w.s([ln0], 'nn0zd', '( %s -> l e. ZZ )' % A4)
kln0 = w.s([kn0, ln0], 'nn0addcld', '( %s -> %s e. NN0 )' % (A4, KL))
klz = w.s([kln0], 'nn0zd', '( %s -> %s e. ZZ )' % (A4, KL))
kre = w.s([kn0], 'nn0red', '( %s -> k e. RR )' % A4)
lre = w.s([ln0], 'nn0red', '( %s -> l e. RR )' % A4)
klek = linarith(w, A4, [w.s([ln0], 'nn0ge0d', '( %s -> 0 <_ l )' % A4)], 'k <_ %s' % KL, leaves={'k': ('RR', kre), 'l': ('RR', lre)})
klel = linarith(w, A4, [w.s([kn0], 'nn0ge0d', '( %s -> 0 <_ k )' % A4)], 'l <_ %s' % KL, leaves={'k': ('RR', kre), 'l': ('RR', lre)})
uzk = w.s([w.s([w.s([kz, klz, klek], '3jca', '( %s -> ( k e. ZZ /\\ %s e. ZZ /\\ k <_ %s ) )' % (A4, KL, KL)), w.inst('eluz2')], 'sylibr', '( %s -> %s e. ( ZZ>= ` k ) )' % (A4, KL)), w.inst('uzss')], 'syl', '( %s -> ( ZZ>= ` %s ) C_ ( ZZ>= ` k ) )' % (A4, KL))
uzl = w.s([w.s([w.s([lz, klz, klel], '3jca', '( %s -> ( l e. ZZ /\\ %s e. ZZ /\\ l <_ %s ) )' % (A4, KL, KL)), w.inst('eluz2')], 'sylibr', '( %s -> %s e. ( ZZ>= ` l ) )' % (A4, KL)), w.inst('uzss')], 'syl', '( %s -> ( ZZ>= ` %s ) C_ ( ZZ>= ` l ) )' % (A4, KL))
raph2 = w.s([w.s([uzk, w.s([], 'ssralv', '( ( ZZ>= ` %s ) C_ ( ZZ>= ` k ) -> ( %s -> %s ) )' % (KL, RA('k', 'ph'), RA(KL, 'ph')))], 'syl', '( %s -> ( %s -> %s ) )' % (A4, RA('k', 'ph'), RA(KL, 'ph'))), raph], 'mpd', '( %s -> %s )' % (A4, RA(KL, 'ph')))
raps2 = w.s([w.s([uzl, w.s([], 'ssralv', '( ( ZZ>= ` %s ) C_ ( ZZ>= ` l ) -> ( %s -> %s ) )' % (KL, RA('l', 'ps'), RA(KL, 'ps')))], 'syl', '( %s -> ( %s -> %s ) )' % (A4, RA('l', 'ps'), RA(KL, 'ps'))), raps], 'mpd', '( %s -> %s )' % (A4, RA(KL, 'ps')))
both = w.s([w.s([w.s([], 'r19.26', '( %s <-> ( %s /\\ %s ) )' % (RA(KL, '( ph /\\ ps )'), RA(KL, 'ph'), RA(KL, 'ps')))], 'a1i', '( %s -> ( %s <-> ( %s /\\ %s ) ) )' % (A4, RA(KL, '( ph /\\ ps )'), RA(KL, 'ph'), RA(KL, 'ps'))), w.s([raph2, raps2], 'jca', '( %s -> ( %s /\\ %s ) )' % (A4, RA(KL, 'ph'), RA(KL, 'ps')))], 'mpbird', '( %s -> %s )' % (A4, RA(KL, '( ph /\\ ps )')))
cbm = w.s([w.s([w.s([], 'id', '( m = %s -> m = %s )' % (KL, KL))], 'fveq2d', '( m = %s -> ( ZZ>= ` m ) = ( ZZ>= ` %s ) )' % (KL, KL))], 'raleqdv', '( m = %s -> ( %s <-> %s ) )' % (KL, RA('m', '( ph /\\ ps )'), RA(KL, '( ph /\\ ps )')))
core = w.s([w.s([kln0, both], 'jca', '( %s -> ( %s e. NN0 /\\ %s ) )' % (A4, KL, RA(KL, '( ph /\\ ps )'))), w.s([cbm], 'rspcev', '( ( %s e. NN0 /\\ %s ) -> %s )' % (KL, RA(KL, '( ph /\\ ps )'), GOAL))], 'syl', '( %s -> %s )' % (A4, GOAL))
# eliminate the two witnesses
# eliminate the two witnesses: the core, rearranged
core2 = w.s([w.s([core], 'ex', '( ( ( k e. NN0 /\\ l e. NN0 ) /\\ %s ) -> ( %s -> %s ) )' % (RA('k', 'ph'), RA('l', 'ps'), GOAL))], 'ex', '( ( k e. NN0 /\\ l e. NN0 ) -> ( %s -> ( %s -> %s ) ) )' % (RA('k', 'ph'), RA('l', 'ps'), GOAL))
core3 = w.s([core2], 'com23', '( ( k e. NN0 /\\ l e. NN0 ) -> ( %s -> ( %s -> %s ) ) )' % (RA('l', 'ps'), RA('k', 'ph'), GOAL))
A3 = '( ( ( %s /\\ k e. NN0 ) /\\ %s ) /\\ l e. NN0 )' % (H, RA('k', 'ph'))
kn0A = w.s([], 'simplll', '( %s -> k e. NN0 )' % A3)
w.lines.pop()
kn0A = w.s([w.s([], 'simpll', '( %s -> ( %s /\\ k e. NN0 ) )' % (A3, H))], 'simprd', '( %s -> k e. NN0 )' % A3)
ln0A = w.s([], 'simpr', '( %s -> l e. NN0 )' % A3)
raphA = w.s([], 'simplr', '( %s -> %s )' % (A3, RA('k', 'ph')))
kl2 = w.s([kn0A, ln0A], 'jca', '( %s -> ( k e. NN0 /\\ l e. NN0 ) )' % A3)
c3a = w.s([kl2, core3], 'syl', '( %s -> ( %s -> ( %s -> %s ) ) )' % (A3, RA('l', 'ps'), RA('k', 'ph'), GOAL))
c3b = w.s([raphA, c3a], 'mpid', '( %s -> ( %s -> %s ) )' % (A3, RA('l', 'ps'), GOAL))
A2 = '( ( %s /\\ k e. NN0 ) /\\ %s )' % (H, RA('k', 'ph'))
lim2 = w.s([c3b], 'rexlimdva', '( %s -> ( %s -> %s ) )' % (A2, EV('l', 'ps'), GOAL))
ex2A = w.s([w.s([ex2], 'adantr', '( ( %s /\\ k e. NN0 ) -> %s )' % (H, EV('l', 'ps')))], 'adantr', '( %s -> %s )' % (A2, EV('l', 'ps')))
inner = w.s([lim2, ex2A], 'mpd', '( %s -> %s )' % (A2, GOAL))
inner2 = w.s([inner], 'ex', '( ( %s /\\ k e. NN0 ) -> ( %s -> %s ) )' % (H, RA('k', 'ph'), GOAL))
lim1 = w.s([inner2], 'rexlimdva', '( %s -> ( %s -> %s ) )' % (H, EV('k', 'ph'), GOAL))
w.qed([lim1, ex1], 'mpd', '( %s -> %s )' % (H, GOAL))
run(w)

# ------------------------------------------------------------ extrwevim
w = W('extrwevim', 'An eventual statement may be weakened pointwise: with ph eventually and ph implying ps at every n, ps holds eventually (the companion schema of extrwevan).')
RA = lambda v, p: 'A. n e. ( ZZ>= ` %s ) %s' % (v, p)
EV = lambda v, p: 'E. %s e. NN0 %s' % (v, RA(v, p))
IM = 'A. n e. NN0 ( ph -> ps )'
H = '( %s /\\ %s )' % (EV('m', 'ph'), IM)
cbk = w.s([w.s([w.s([], 'id', '( m = k -> m = k )')], 'fveq2d', '( m = k -> ( ZZ>= ` m ) = ( ZZ>= ` k ) )')], 'raleqdv', '( m = k -> ( %s <-> %s ) )' % (RA('m', 'ph'), RA('k', 'ph')))
ex1 = w.s([w.s([], 'simpl', '( %s -> %s )' % (H, EV('m', 'ph'))), w.s([w.s([cbk], 'cbvrexvw', '( %s <-> %s )' % (EV('m', 'ph'), EV('k', 'ph')))], 'a1i', '( %s -> ( %s <-> %s ) )' % (H, EV('m', 'ph'), EV('k', 'ph')))], 'mpbid', '( %s -> %s )' % (H, EV('k', 'ph')))
A2 = '( ( %s /\\ k e. NN0 ) /\\ %s )' % (H, RA('k', 'ph'))
kn0 = w.s([w.s([], 'simpl', '( %s -> ( %s /\\ k e. NN0 ) )' % (A2, H))], 'simprd', '( %s -> k e. NN0 )' % A2)
hA = w.s([w.s([], 'simpl', '( %s -> ( %s /\\ k e. NN0 ) )' % (A2, H))], 'simpld', '( %s -> %s )' % (A2, H))
imA = w.s([hA], 'simprd', '( %s -> %s )' % (A2, IM))
raph = w.s([], 'simpr', '( %s -> %s )' % (A2, RA('k', 'ph')))
kuz = w.s([kn0, w.s([w.s([], 'nn0uz', 'NN0 = ( ZZ>= ` 0 )')], 'a1i', '( %s -> NN0 = ( ZZ>= ` 0 ) )' % A2)], 'eleqtrd', '( %s -> k e. ( ZZ>= ` 0 ) )' % A2)
ss1 = w.s([kuz, w.inst('uzss')], 'syl', '( %s -> ( ZZ>= ` k ) C_ ( ZZ>= ` 0 ) )' % A2)
ss2 = w.s([ss1, w.s([w.s([w.s([], 'nn0uz', 'NN0 = ( ZZ>= ` 0 )')], 'eqcomd' if False else 'a1i', '( %s -> NN0 = ( ZZ>= ` 0 ) )' % A2)], 'eqcomd', '( %s -> ( ZZ>= ` 0 ) = NN0 )' % A2)], 'sseqtrd', '( %s -> ( ZZ>= ` k ) C_ NN0 )' % A2)
imk = w.s([w.s([ss2, w.s([], 'ssralv', '( ( ZZ>= ` k ) C_ NN0 -> ( %s -> %s ) )' % (IM, RA('k', '( ph -> ps )')))], 'syl', '( %s -> ( %s -> %s ) )' % (A2, IM, RA('k', '( ph -> ps )'))), imA], 'mpd', '( %s -> %s )' % (A2, RA('k', '( ph -> ps )')))
raps = w.s([w.s([imk, w.s([], 'ralim', '( %s -> ( %s -> %s ) )' % (RA('k', '( ph -> ps )'), RA('k', 'ph'), RA('k', 'ps')))], 'syl', '( %s -> ( %s -> %s ) )' % (A2, RA('k', 'ph'), RA('k', 'ps'))), raph], 'mpd', '( %s -> %s )' % (A2, RA('k', 'ps')))
cbm = w.s([w.s([w.s([], 'id', '( m = k -> m = k )')], 'fveq2d', '( m = k -> ( ZZ>= ` m ) = ( ZZ>= ` k ) )')], 'raleqdv', '( m = k -> ( %s <-> %s ) )' % (RA('m', 'ps'), RA('k', 'ps')))
goal = w.s([w.s([kn0, raps], 'jca', '( %s -> ( k e. NN0 /\\ %s ) )' % (A2, RA('k', 'ps'))), w.s([cbm], 'rspcev', '( ( k e. NN0 /\\ %s ) -> %s )' % (RA('k', 'ps'), EV('m', 'ps')))], 'syl', '( %s -> %s )' % (A2, EV('m', 'ps')))
lim = w.s([w.s([goal], 'ex', '( ( %s /\\ k e. NN0 ) -> ( %s -> %s ) )' % (H, RA('k', 'ph'), EV('m', 'ps')))], 'rexlimdva', '( %s -> ( %s -> %s ) )' % (H, EV('k', 'ph'), EV('m', 'ps')))
w.qed([lim, ex1], 'mpd', '( %s -> %s )' % (H, EV('m', 'ps')))
run(w)
